3	namespace App\Http\Controllers\Auth;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\User;
7	use App\Models\UserCategory;
8	use Illuminate\Auth\Events\Registered;
9	use Illuminate\Http\RedirectResponse;
10	use Illuminate\Http\Request;
11	use Illuminate\Support\Facades\Hash;
12	use Illuminate\Validation\Rules\Password;
13	use Illuminate\View\View;
14	
15	class RegisteredUserController extends Controller
16	{
17	    /**
18	     * Display the registration view.
19	     */
20	    public function create(): View
21	    {
22	        return view('auth.register');
23	    }
24	
25	    /**
26	     * Handle an incoming registration request.
27	     *
28	     * @throws \Illuminate\Validation\ValidationException
29	     */
30	    public function store(Request $request): RedirectResponse
31	    {
32	        $data = $request->validate([
33	            'firstname' => ['required', 'string', 'max:255'],
34	            'lastname' => ['required', 'string', 'max:255'],
35	            'email' => ['required', 'string', 'email', 'max:255', 'unique:'.User::class],
36	            'city' => ['required', 'string', 'max:255'],
37	            'zip_code' => ['required', 'string', 'max:255'],
38	            'address' => ['required', 'string', 'max:255'],
39	            'province' => ['required', 'string', 'max:255'],
40	            'user_type' => ['required', 'string', 'max:255'],
41	            'company_name' => ['required', 'string', 'max:255'],
42	            'phone' => ['required', 'string', 'max:255'],
43	            'vat_number' => ['required', 'string', 'max:255'],
44	            'password' => ['required', 'confirmed', Password::defaults()],
45	        ], [], [
46	            'firstname' => __('validation.attributes.first_name'),
47	            'lastname' => __('validation.attributes.last_name'),
48	            'zip_code' => __('Zip / Postal Code'),
49	            'province' => __('validation.attributes.province'),
50	            'user_type' => __('form.label_user_type'),
51	            'vat_number' => __('VAT Number'),
52	        ]);
53	
54	        $user = User::create([
55	            'firstname' => $request->firstname,
56	            'lastname' => $request->lastname,
57	            'email' => $request->email,
58	            'city' => $request->city,
59	            'zip_code' => $request->zip_code,
60	            'address' => $request->address,
61	            'province' => $request->province,
62	            'user_type' => $request->user_type,
63	            'company_name' => $request->company_name,
64	            'phone' => $request->phone,
65	            'vat_number' => $request->vat_number,
66	            'password' => Hash::make($request->password),
67	        ]);
68	
69	        event(new Registered($user));
70	
71	        // associate user to category
72	        $selectedCategory = UserCategory::where('code', $data['user_type'])->first();
73	        if (!$selectedCategory) {
74	            abort(400);
75	        }
76	        $user->categories()->save($selectedCategory);
77	
78	        // we do not login user, as it will be requested to verify email before being able to login
79	        //Auth::login($user);
80	
81	        return redirect(route('register.success'))->with(['status' => 1]);
82	    }
83	
84	
85	    /**
86	     * Shwo confirmation page
87	     */
88	    public function success()
89	    {
90	        if (session('status') !== 1) {
91	            return redirect('register');
92	        }
93	
94	        return view('auth.register', [
95	            'response' => __('register.msg_success')
96	        ]);
97	    }
98	}
